#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/basic_controls.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// VisualInspectorOverlay's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/visual_inspector_overlay.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The stable ID of the control the overlay outlines; empty for none.
template <typename Declaring>
struct VisualInspectorOverlayTargetStableIdCapability {
    PropertyCell<std::string, VisualInspectorOverlayTargetStableIdCapability<Declaring>> target_stable_id{std::string{}};

    static void assign(VisualInspectorOverlayTargetStableIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.target_stable_id), incoming);
        if (!capability.target_stable_id.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.target_stable_id));
    }
};

// Every VisualInspectorOverlay capability, in the order the declaring class takes them.
template <typename Declaring>
struct VisualInspectorOverlayCapabilities : public VisualInspectorOverlayTargetStableIdCapability<Declaring> {};

} // namespace gui_forms
